  "The app doesn&apos;t just use a single API. For backtests, it first queries the active": "Die App verwendet nicht nur eine einzige API. Bei Backtests werden zunächst die Aktiven abgefragt",
  "The app multiplies this rate by your shares held to calculate your donation.": "Die App multipliziert diesen Satz mit deinen gehaltenen Anteilen, um deine Spende zu berechnen.",
