  "The best tested strategy is ahead by": "Die am besten getestete Strategie liegt vor uns",
  "The file is not yet automatically converted into transactions. The next logical step is therefore the manual ledger with account pre-selection.": "Die Datei wird noch nicht automatisch in Transaktionen umgewandelt. Der nächste logische Schritt ist daher das manuelle Hauptbuch mit Kontenvorauswahl.",
  "The mobile app keeps the daily portfolio tools and the finance settings that are ready for small screens.": "Die mobile App hält die täglichen Portfolio-Tools und die Finanzeinstellungen für kleine Bildschirme bereit.",
  "The orange line in the chart shows how the ratio evolves through the selected range.": "Die orangefarbene Linie im Diagramm zeigt, wie sich das Verhältnis im ausgewählten Bereich entwickelt.",
  "The page keeps the last local structure until pricing becomes available again.": "Die Seite behält die letzte lokale Struktur bei, bis die Preise wieder verfügbar sind.",
  "These rules apply regardless of your tax profile.": "Diese Regeln gelten unabhängig von deinem Steuerprofil.",
  "Thinking…": "Thinking…",
