  "This account view is built from local ledger entries.": "Diese Kontoansicht wird aus lokalen Hauptbucheinträgen erstellt.",
  "This page is advanced. Use it when you want to test a strategy idea, not for everyday portfolio checking.": "This page is advanced. Verwende es, wenn du eine Strategieidee testen möchtest, nicht für die alltägliche Portfolioüberprüfung.",
  "This usually reflects a more defensive metals regime with gold carrying most of the signal.": "Dies spiegelt normalerweise ein defensiveres Metallregime wider, wobei Gold das meiste Signal liefert.",
  "Threshold — if you exceed €1,000, the full amount becomes taxable (not just the excess).": "Schwellenwert – wenn du 1.000 € überschreitest, wird der gesamte Betrag steuerpflichtig (nicht nur der Überschuss).",
