  "Use screening apps like Zoya or Musaffa to check the \"Impermissible Income\" or \"Interest income\" ratio for your holdings.": "Verwende Screening-Apps wie Zoya oder Musaffa, um das Verhältnis „Unzulässiges Einkommen“ oder „Zinseinkommen“ für deine Bestände zu überprüfen.",
  "Use Source to separate demo rows from your manual entries.": "Verwende „Quelle“, um Demozeilen von deinen manuellen Einträgen zu trennen.",
