  "The app doesn&apos;t just use a single API. For backtests, it first queries the active": "لا يستخدم التطبيق واجهة برمجة تطبيقات واحدة فقط. بالنسبة للاختبارات الخلفية، فإنه يستعلم أولاً عن النشط",
  "The app multiplies this rate by your shares held to calculate your donation.": "يقوم التطبيق بضرب هذا المعدل من خلال أسهمك المحتفظ بها لحساب تبرعك.",
  "The best SMA varies between segments ({periods}), indicating changing market conditions.": "ويختلف أفضل SMA بين القطاعات ({periods})، مما يشير إلى ظروف السوق المتغيرة.",
  "The best tested strategy is ahead by": "أفضل استراتيجية تم اختبارها هي في المقدمة",
  "The file is not yet automatically converted into transactions. The next logical step is therefore the manual ledger with account pre-selection.": "لم يتم تحويل الملف تلقائيًا إلى معاملات بعد. وبالتالي فإن الخطوة المنطقية التالية هي دفتر الأستاذ اليدوي مع الاختيار المسبق للحساب.",
  "The mobile app keeps the daily portfolio tools and the finance settings that are ready for small screens.": "يحتفظ تطبيق الهاتف المحمول بأدوات المحفظة اليومية والإعدادات المالية الجاهزة للشاشات الصغيرة.",
  "The orange line in the chart shows how the ratio evolves through the selected range.": "يوضح الخط البرتقالي في الرسم البياني كيفية تطور النسبة عبر النطاق المحدد.",
  "The page keeps the last local structure until pricing becomes available again.": "تحتفظ الصفحة بالبنية المحلية الأخيرة حتى يصبح التسعير متاحًا مرة أخرى.",
