  "This action is permanent and will delete all your data from Firebase.": "هذا الإجراء دائم وسيتم حذف جميع بياناتك من Firebase.",
  "This account does not exist anymore or the local data was cleared.": "هذا الحساب لم يعد موجودًا أو تم مسح البيانات المحلية.",
  "This account view is built from local ledger entries.": "تم إنشاء عرض الحساب هذا من إدخالات دفتر الأستاذ المحلي.",
  "This page is advanced. Use it when you want to test a strategy idea, not for everyday portfolio checking.": "هذه الصفحة متقدمة. استخدمه عندما تريد اختبار فكرة استراتيجية، وليس لفحص المحفظة اليومية.",
  "This usually reflects a more defensive metals regime with gold carrying most of the signal.": "ويعكس هذا عادة نظام معادن أكثر دفاعية حيث يحمل الذهب معظم الإشارة.",
  "Threshold — if you exceed €1,000, the full amount becomes taxable (not just the excess).": "الحد الأدنى — إذا تجاوزت 1000 يورو، يصبح المبلغ بالكامل خاضعًا للضريبة (وليس فقط الفائض).",
