  "Track crypto, stocks, gold, and silver in one portfolio, analyze price history, backtest strategies, and review German tax estimates.": "تتبع العملات المشفرة والأسهم والذهب والفضة في محفظة واحدة، وقم بتحليل تاريخ الأسعار، واستراتيجيات الاختبار العكسي، ومراجعة تقديرات الضرائب الألمانية.",
