  "Use a local session until a cloud system is connected.": "استخدم جلسة محلية حتى يتم توصيل النظام السحابي.",
  "Use screening apps like Zoya or Musaffa to check the \"Impermissible Income\" or \"Interest income\" ratio for your holdings.": "استخدم تطبيقات الفحص مثل Zoya أو Musaffa للتحقق من نسبة \"الدخل غير المسموح به\" أو \"دخل الفوائد\" لممتلكاتك.",
