  "Use the filters below to inspect buys, sells, dividends, fees, transfers, and cash movements.": "استخدم عوامل التصفية أدناه لفحص عمليات الشراء والبيع وتوزيعات الأرباح والرسوم والتحويلات والحركات النقدية.",
