  "Silver looks deeply undervalued": "تبدو الفضة مقومة بأقل من قيمتها الحقيقية بشكل كبير",
  "A very high ratio means silver is cheap relative to gold and may offer more catch-up potential.": "النسبة العالية جدًا تعني أن الفضة رخيصة مقارنة بالذهب وقد توفر المزيد من إمكانات اللحاق بالركب.",
  "Silver looks moderately undervalued": "تبدو الفضة مقومة بأقل من قيمتها الحقيقية بشكل معتدل",
  "Gold still trades at a premium to silver, but the imbalance is less stretched than in extreme regimes.": "لا يزال الذهب يتداول بعلاوة على الفضة، لكن الخلل أقل حدة مما هو عليه في الأنظمة المتطرفة.",
  "Silver looks fairly valued": "تبدو الفضة مقومة بقيمة عادلة",
