  "Silver looks relatively overvalued": "تبدو الفضة مقومة بأكثر من قيمتها الحقيقية نسبيًا",
  "A low ratio means silver has already outperformed gold and may be trading rich versus its usual relationship.": "النسبة المنخفضة تعني أن الفضة قد تفوقت بالفعل على الذهب وقد يتم تداولها بسعر مرتفع مقارنة بعلاقتها المعتادة.",
  "Gold dominance is stretched": "هيمنة الذهب ممتدة",
  "Silver is lagging materially. Useful for users watching defensive metal positioning.": "الفضة تتخلف بشكل كبير. مفيد للمستخدمين الذين يراقبون مراكز المعادن الدفاعية.",
  "Gold still leads": "لا يزال الذهب يقود",
  "This usually reflects a more defensive metals regime with gold carrying most of the signal.": "يعكس هذا عادة نظام معادن أكثر دفاعية حيث يحمل الذهب معظم الإشارة.",
  "Metals are balanced": "المعادن متوازنة",
  "Gold and silver are trading in a more neutral relationship, which is easier to compare over time.": "يتم تداول الذهب والفضة في علاقة أكثر حيادية، والتي يسهل مقارنتها بمرور الوقت.",
  "Silver is leading": "الفضة تقود",
