  'Track crypto, stocks, gold, and silver in one portfolio, analyze price history, backtest strategies, and review German tax estimates.':
    'Verfolge Krypto, Aktien, Gold und Silber in einem Portfolio, analysiere Kursverläufe, teste Strategien und prüfe deutsche Steuerschätzungen.',
  'Estimate what your realized gains, FIFO disposals, and annual tax buckets could look like.':
    'Schätze, wie deine realisierten Gewinne, FIFO-Verkäufe und jährlichen Steuerkörbe aussehen könnten.',
  'A plain-English guess at what you might owe in Germany this year, based on the trades you\'ve entered. Not an official tax return.':
    'Eine leicht verständliche Schätzung, was du in Deutschland dieses Jahr auf Basis deiner eingetragenen Trades zahlen könntest. Keine offizielle Steuererklärung.',
  'New to German crypto & investing taxes?': 'Neu bei deutschen Krypto- und Investmentsteuern?',
  'Three quick steps to read this page without getting lost.':
    'Drei schnelle Schritte, um diese Seite ohne Verwirrung zu lesen.',
  'Pick a year below — the big number at the top is your rough tax guess for that year.':
    'Wähle unten ein Jahr aus — die große Zahl oben ist deine grobe Steuerschätzung für dieses Jahr.',
  'Skim the four colored tiles: they show how each bucket (stocks/ETFs vs. crypto/metals) contributes.':
    'Überfliege die vier farbigen Kacheln: Sie zeigen, wie jeder Korb (Aktien/ETFs vs. Krypto/Metalle) beiträgt.',
  'Scroll to "Key concepts" below if any term feels unfamiliar — everything is explained in plain English.':
    'Scrolle zu „Wichtige Konzepte“, wenn dir ein Begriff unbekannt vorkommt — alles wird einfach erklärt.',
  'If the numbers look off, fix them in Transactions. This page only reads what you\'ve entered there.':
    'Wenn die Zahlen falsch wirken, korrigiere sie in Transaktionen. Diese Seite liest nur, was du dort eingetragen hast.',
