  'Pick the year to inspect and your personal income tax bracket. Not sure? 32% is a reasonable middle-ground guess.':
    'Wähle das Jahr und deinen persönlichen Einkommensteuersatz. Wenn du unsicher bist, sind 32 % ein brauchbarer Mittelwert.',
  'Applied to short-term crypto & metal profits only.':
    'Gilt nur für kurzfristige Gewinne aus Krypto und Metallen.',
  'Stocks & ETFs + Crypto & Metals, combined.': 'Aktien & ETFs + Krypto & Metalle zusammen.',
