  'Taxable ledger events': 'أحداث السجل الخاضعة للضريبة',
  'Pick the year to inspect and your personal income tax bracket. Not sure? 32% is a reasonable middle-ground guess.':
    'اختر السنة التي تريد فحصها وشريحتك الضريبية الشخصية. لست متأكدًا؟ 32% تقدير متوسط معقول.',
  'Applied to short-term crypto & metal profits only.':
    'يُطبق على أرباح العملات الرقمية والمعادن قصيرة الأجل فقط.',
  'Stocks & ETFs + Crypto & Metals, combined.': 'الأسهم وصناديق ETF + العملات الرقمية والمعادن مجتمعة.',
  'Profit above the €1,000 saver allowance. Taxed at ~26.375%.':
    'الربح فوق إعفاء الادخار البالغ 1,000 €. يخضع لضريبة تقارب 26.375%.',
  'Short-term profit taxed at your income rate. Held > 1 year? Tax-free.':
    'الربح قصير الأجل يُفرض عليه معدل ضريبة الدخل الخاص بك. إذا كانت مدة الاحتفاظ أكثر من سنة؟ فهو معفى من الضريبة.',
  'How much more you could profit this year before any tax kicks in.':
    'هذا هو مقدار الربح الإضافي الذي يمكنك تحقيقه هذا العام قبل بدء أي ضريبة.',
  "Your net profit, what's already tax-free, and what the tax comes out to — broken down by asset type.":
    'صافي ربحك، وما هو معفى بالفعل من الضريبة، وما تنتهي إليه الضريبة — مفصل حسب نوع الأصل.',
  'Tax-free after 1 year · otherwise your income rate':
    'معفى بعد سنة واحدة · وإلا فيُطبق معدل ضريبة الدخل الخاص بك',
