  'Taxable': 'خاضع للضريبة',
  'Estimated tax': 'الضريبة المقدرة',
  'Flat ~26.375% on profit above €1,000': 'معدل ثابت يقارب 26.375% على الأرباح فوق 1,000 €',
  'German tax law keeps stocks/ETFs separate from crypto/metals. Each has its own tax-free allowance.':
    'يفصل القانون الضريبي الألماني بين الأسهم/صناديق ETF وبين العملات الرقمية/المعادن. ولكل فئة سماحها الضريبي الخاص.',
