  Amount: 'الكمية',
  'One card per asset type, written in plain English, with your numbers for 2026 at the bottom.':
    'بطاقة واحدة لكل نوع أصل، مكتوبة بلغة بسيطة، مع أرقامك لعام 2026 في الأسفل.',
  'Hold for more than 1 year → profit is tax-free. Sell earlier → profit is taxed at your personal income rate. Swapping one coin for another counts as a sale.':
    'الاحتفاظ لأكثر من سنة واحدة → الربح معفى من الضريبة. البيع قبل ذلك → الربح يُفرض عليه معدل ضريبة الدخل الشخصي. مبادلة عملة بأخرى تُعد عملية بيع.',
  'Taxed at a flat ~26.375% on profit above the €1,000 yearly saver allowance. No matter how long you held — the 1-year rule doesn\'t apply here.':
    'يُفرض معدل ثابت يقارب 26.375% على الأرباح فوق إعفاء الادخار السنوي البالغ 1,000 €. بغض النظر عن مدة الاحتفاظ — لا تنطبق هنا قاعدة السنة الواحدة.',
  'Same rules as stocks: flat ~26.375% on profit above the €1,000 saver allowance. Shown separately so you can track your ETF sleeve on its own.':
    'تنطبق نفس قواعد الأسهم: معدل ثابت يقارب 26.375% على الأرباح فوق إعفاء الادخار البالغ 1,000 €. يتم عرضها بشكل منفصل حتى تتمكن من متابعة شريحة ETF وحدها.',
  'Physical gold and silver follow the same rule as crypto: tax-free after 1 year, taxed at your income rate if sold earlier.':
    'يتبع الذهب والفضة الماديان القاعدة نفسها المطبقة على العملات الرقمية: إعفاء بعد سنة واحدة، وضريبة بمعدل دخلك إذا تم البيع قبل ذلك.',
  'For Halal investors: the suggested amount to donate so your returns stay Shariah-compliant. This is separate from taxes and doesn\'t change the numbers above.':
    'للمستثمرين الحلال: هذا هو المبلغ المقترح للتبرع به حتى تبقى عوائدك متوافقة مع الشريعة. وهو منفصل عن الضرائب ولا يغيّر الأرقام أعلاه.',
  'In plain English:': 'بصياغة مبسطة:',
  "even Shariah-screened ETFs & stocks hold a tiny amount of interest income you're supposed to give away. Some ETFs (Wahed, SP Funds) do this for you. For the others, this card tells you roughly how much to donate.":
    'حتى صناديق ETF والأسهم التي تمت فلترتها وفق الشريعة تحتوي على قدر صغير من دخل الفائدة الذي يفترض التخلص منه. بعض الصناديق (Wahed وSP Funds) تقوم بذلك نيابة عنك. أما البقية فتعطيك هذه البطاقة تقديرًا تقريبيًا لما ينبغي التبرع به.',
