function getDictionary(language: LanguagePreference): Record<string, string> {
  if (language === 'de') return { ...GENERATED_DE_TEXT, ...DE_TEXT, ...REFINED_DE_TEXT, ...V124_DE_TEXT };
  if (language === 'ar') {
    return {
      ...GENERATED_AR_TEXT,
      ...AR_TEXT,
      ...REFINED_AR_TEXT,
      ...V124_AR_TEXT,
      'Back to login': 'العودة إلى تسجيل الدخول',
      'Shariah Audit': 'تدقيق الشريعة',
      'Verify your email': 'تأكيد البريد الإلكتروني',
      'Tax & Purification': 'الضرائب والتطهير',
      'Purification Settings': 'إعدادات التطهير',
      'Tax Profile': 'الملف الضريبي',
      'Personal Finance': 'التمويل الشخصي',
      'tab above': 'التبويب أعلاه',
      'Profile imported successfully': 'تم استيراد الملف بنجاح',
      'Invalid profile file': 'ملف غير صالح',
      'We sent a 6-digit code to': 'لقد أرسلنا رمزاً مكوناً من 6 أرقام إلى',
      'Verification successful!': 'تم التحقق بنجاح!',
      'Verify Code': 'تأكيد الرمز',
    };
  }
  return {};
}

export function normalizeTranslatableText(value: string): string {
  return value.replace(/\s+/g, ' ').trim();
}

export function translateAppText(value: string, language: LanguagePreference): string {
  const normalized = normalizeTranslatableText(value);
  if (!normalized) return value;

  const corrected = SOURCE_CORRECTIONS[normalized] ?? normalized;
  if (language === 'en') {
    return SOURCE_CORRECTIONS[normalized] ?? value;
  }

  const dictionary = getDictionary(language);
  if (dictionary[corrected]) {
    return dictionary[corrected];
  }

  if (dictionary[normalized]) {
    return dictionary[normalized];
  }

  for (const pattern of PATTERN_TRANSLATORS) {
    const correctedMatch = pattern.regex.exec(corrected);
    if (correctedMatch) {
      return pattern.translate(correctedMatch, language) ?? value;
    }

    const originalMatch = pattern.regex.exec(normalized);
    if (originalMatch) {
      return pattern.translate(originalMatch, language) ?? value;
    }
  }

  return SOURCE_CORRECTIONS[normalized] ?? value;
}

export function getEnglishKey(translatedValue: string, language: LanguagePreference): string {
  const normalized = normalizeTranslatableText(translatedValue);
  if (!normalized) return translatedValue;

  const dictionary = getDictionary(language);
  for (const [key, val] of Object.entries(dictionary)) {
    if (val === normalized) {
      return key;
    }
  }

  return translatedValue;
}
